sql.if:
AND EXISTS (
  SELECT 1 FROM purchase_proposal_channels pc
  JOIN channels c ON c.id = pc.channel_id AND c.is_active = 1

    JOIN user_channels uc ON uc.channel_id = c.id AND uc.user_id = #{filter.viewerId}

  WHERE pc.proposal_id = p.id
  AND c.id = #{filter.channelId}
)

AND EXISTS (
  SELECT 1 FROM proposal_tags pt
  JOIN tags t ON t.id = pt.tag_id AND t.is_active = 1
  WHERE pt.proposal_id = p.id AND t.id = #{filter.tagId}
)

mapper.select:
SELECT id FROM channels WHERE is_active = 1 AND id IN
#{id}
FOR SHARE

mapper.delete:
DELETE FROM user_channels WHERE user_id = #{viewerId}

  AND channel_id NOT IN
  #{id}

mapper.sql:
(
  SELECT MAX(id) AS id FROM decision_votes
  WHERE proposal_id = #{proposalId}
  GROUP BY voter_user_id
) latest
JOIN decision_votes v ON v.id = latest.id

mapper.select:
SELECT id, content, created_at FROM proposal_updates
WHERE proposal_id = #{proposalId}
ORDER BY created_at, id
LIMIT #{size} OFFSET #{offset}

mapper.sql:
c.proposal_id = #{proposalId}
AND (
  (c.comment_status = 'VISIBLE' AND (c.parent_comment_id IS NULL OR EXISTS (
    SELECT 1 FROM proposal_comments parent
    WHERE parent.id = c.parent_comment_id AND parent.proposal_id = c.proposal_id
      AND parent.comment_status IN ('VISIBLE', 'DELETED')
  )))
  OR (c.comment_status = 'DELETED' AND c.parent_comment_id IS NULL AND EXISTS (
    SELECT 1 FROM proposal_comments reply
    WHERE reply.parent_comment_id = c.id AND reply.proposal_id = c.proposal_id
      AND reply.comment_status = 'VISIBLE'
  ))
)

mapper.select:
SELECT 
FROM proposal_comments c JOIN users u ON u.id = c.author_user_id
WHERE c.id = #{commentId}
